CREATE VIEW stg_external_rating_normalized AS (SELECT dg.GameID, ge.GameEditionID, 1 AS RatingSourceID, 1 AS RatingTypeID, CAST(TRY_CAST(ps5.Metacritic AS DOUBLE) AS DECIMAL(8,2)) AS RawRatingValue, CAST(TRY_CAST(ps5.Metacritic AS DOUBLE) AS DECIMAL(4,2)) AS RatingValue, CAST(NULL AS DATE) AS ObservationDate FROM stg_ps5_inventory AS ps5 INNER JOIN Game AS dg ON ((dg.GameTitle = main."trim"(ps5.Title))) INNER JOIN Platform AS p ON ((p.PlatformName = 'PS5')) INNER JOIN GameEdition AS ge ON (((ge.GameID = dg.GameID) AND (ge.PlatformID = p.PlatformID))) WHERE (TRY_CAST(ps5.Metacritic AS DOUBLE) BETWEEN 0 AND 10)) UNION ALL (((((SELECT dg.GameID, ge.GameEditionID, 2, 1, CAST(TRY_CAST(ps5.OpenCritic AS DOUBLE) AS DECIMAL(8,2)), CAST(TRY_CAST(ps5.OpenCritic AS DOUBLE) AS DECIMAL(4,2)), CAST(NULL AS DATE) FROM stg_ps5_inventory AS ps5 INNER JOIN Game AS dg ON ((dg.GameTitle = main."trim"(ps5.Title))) INNER JOIN Platform AS p ON ((p.PlatformName = 'PS5')) INNER JOIN GameEdition AS ge ON (((ge.GameID = dg.GameID) AND (ge.PlatformID = p.PlatformID))) WHERE (TRY_CAST(ps5.OpenCritic AS DOUBLE) BETWEEN 0 AND 10)) UNION ALL (SELECT dg.GameID, ge.GameEditionID, 3, 1, CAST(TRY_CAST(ps5."IGDB Critic Score" AS DOUBLE) AS DECIMAL(8,2)), CAST((TRY_CAST(ps5."IGDB Critic Score" AS DOUBLE) / 10.0) AS DECIMAL(4,2)), CAST(NULL AS DATE) FROM stg_ps5_inventory AS ps5 INNER JOIN Game AS dg ON ((dg.GameTitle = main."trim"(ps5.Title))) INNER JOIN Platform AS p ON ((p.PlatformName = 'PS5')) INNER JOIN GameEdition AS ge ON (((ge.GameID = dg.GameID) AND (ge.PlatformID = p.PlatformID))) WHERE (TRY_CAST(ps5."IGDB Critic Score" AS DOUBLE) BETWEEN 0 AND 100))) UNION ALL ((SELECT dg.GameID, ge.GameEditionID, 3, 2, CAST(TRY_CAST(ps5."IGDB User Score" AS DOUBLE) AS DECIMAL(8,2)), CAST(TRY_CAST(ps5."IGDB User Score" AS DOUBLE) AS DECIMAL(4,2)), CAST(NULL AS DATE) FROM stg_ps5_inventory AS ps5 INNER JOIN Game AS dg ON ((dg.GameTitle = main."trim"(ps5.Title))) INNER JOIN Platform AS p ON ((p.PlatformName = 'PS5')) INNER JOIN GameEdition AS ge ON (((ge.GameID = dg.GameID) AND (ge.PlatformID = p.PlatformID))) WHERE (TRY_CAST(ps5."IGDB User Score" AS DOUBLE) BETWEEN 0 AND 10)) UNION ALL (SELECT dg.GameID, ge.GameEditionID, 4, 3, CAST(TRY_CAST(ps4."Avg. Score" AS DOUBLE) AS DECIMAL(8,2)), CAST(TRY_CAST(ps4."Avg. Score" AS DOUBLE) AS DECIMAL(4,2)), CAST(NULL AS DATE) FROM stg_ps4_inventory AS ps4 INNER JOIN Game AS dg ON ((dg.GameTitle = main."trim"(ps4.Title))) INNER JOIN Platform AS p ON ((p.PlatformName = 'PS4')) INNER JOIN GameEdition AS ge ON (((ge.GameID = dg.GameID) AND (ge.PlatformID = p.PlatformID))) WHERE (TRY_CAST(ps4."Avg. Score" AS DOUBLE) BETWEEN 0 AND 10)))) UNION ALL (((SELECT dg.GameID, ge.GameEditionID, 1, 1, CAST(TRY_CAST(ps4.Metacritic AS DOUBLE) AS DECIMAL(8,2)), CAST(TRY_CAST(ps4.Metacritic AS DOUBLE) AS DECIMAL(4,2)), CAST(NULL AS DATE) FROM stg_ps4_inventory AS ps4 INNER JOIN Game AS dg ON ((dg.GameTitle = main."trim"(ps4.Title))) INNER JOIN Platform AS p ON ((p.PlatformName = 'PS4')) INNER JOIN GameEdition AS ge ON (((ge.GameID = dg.GameID) AND (ge.PlatformID = p.PlatformID))) WHERE (TRY_CAST(ps4.Metacritic AS DOUBLE) BETWEEN 0 AND 10)) UNION ALL (SELECT dg.GameID, ge.GameEditionID, 2, 1, CAST(TRY_CAST(ps4.OpenCritic AS DOUBLE) AS DECIMAL(8,2)), CAST(TRY_CAST(ps4.OpenCritic AS DOUBLE) AS DECIMAL(4,2)), CAST(NULL AS DATE) FROM stg_ps4_inventory AS ps4 INNER JOIN Game AS dg ON ((dg.GameTitle = main."trim"(ps4.Title))) INNER JOIN Platform AS p ON ((p.PlatformName = 'PS4')) INNER JOIN GameEdition AS ge ON (((ge.GameID = dg.GameID) AND (ge.PlatformID = p.PlatformID))) WHERE (TRY_CAST(ps4.OpenCritic AS DOUBLE) BETWEEN 0 AND 10))) UNION ALL ((SELECT dg.GameID, ge.GameEditionID, 4, 3, CAST(TRY_CAST(wiiu."Avg. Score" AS DOUBLE) AS DECIMAL(8,2)), CAST(TRY_CAST(wiiu."Avg. Score" AS DOUBLE) AS DECIMAL(4,2)), CAST(NULL AS DATE) FROM stg_wiiu_inventory AS wiiu INNER JOIN Game AS dg ON ((dg.GameTitle = main."trim"(wiiu.Title))) INNER JOIN Platform AS p ON ((p.PlatformName = 'Wii U')) INNER JOIN GameEdition AS ge ON (((ge.GameID = dg.GameID) AND (ge.PlatformID = p.PlatformID))) WHERE (TRY_CAST(wiiu."Avg. Score" AS DOUBLE) BETWEEN 0 AND 10)) UNION ALL (SELECT dg.GameID, ge.GameEditionID, 1, 1, CAST(TRY_CAST(wiiu.Metacritic AS DOUBLE) AS DECIMAL(8,2)), CAST(TRY_CAST(wiiu.Metacritic AS DOUBLE) AS DECIMAL(4,2)), CAST(NULL AS DATE) FROM stg_wiiu_inventory AS wiiu INNER JOIN Game AS dg ON ((dg.GameTitle = main."trim"(wiiu.Title))) INNER JOIN Platform AS p ON ((p.PlatformName = 'Wii U')) INNER JOIN GameEdition AS ge ON (((ge.GameID = dg.GameID) AND (ge.PlatformID = p.PlatformID))) WHERE (TRY_CAST(wiiu.Metacritic AS DOUBLE) BETWEEN 0 AND 10))))) UNION ALL (SELECT dg.GameID, ge.GameEditionID, 2, 1, CAST(TRY_CAST(wiiu.OpenCritic AS DOUBLE) AS DECIMAL(8,2)), CAST(TRY_CAST(wiiu.OpenCritic AS DOUBLE) AS DECIMAL(4,2)), CAST(NULL AS DATE) FROM stg_wiiu_inventory AS wiiu INNER JOIN Game AS dg ON ((dg.GameTitle = main."trim"(wiiu.Title))) INNER JOIN Platform AS p ON ((p.PlatformName = 'Wii U')) INNER JOIN GameEdition AS ge ON (((ge.GameID = dg.GameID) AND (ge.PlatformID = p.PlatformID))) WHERE (TRY_CAST(wiiu.OpenCritic AS DOUBLE) BETWEEN 0 AND 10)));
